import React, { useState, useEffect, useContext } from 'react';
import axios from 'axios';
import { useParams, useNavigate } from 'react-router-dom';
import { AuthContext } from '../../context/AuthContext';
import { Typography, Paper, CircularProgress, Button, Box, TextField, Grid, Chip, Alert, Dialog, DialogActions, DialogContent, DialogContentText, DialogTitle } from '@mui/material';
import CheckCircleOutlineIcon from '@mui/icons-material/CheckCircleOutline';
import HighlightOffIcon from '@mui/icons-material/HighlightOff';
import EditNoteIcon from '@mui/icons-material/EditNote';

const MedicationRequestReview = () => {
    const { requestId } = useParams();
    const navigate = useNavigate();
    const { currentUser } = useContext(AuthContext);
    const [request, setRequest] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [nurseNotes, setNurseNotes] = useState('');
    const [actionInProgress, setActionInProgress] = useState(false);
    const [openConfirmDialog, setOpenConfirmDialog] = useState(false);
    const [confirmDialogAction, setConfirmDialogAction] = useState(null); // 'approve', 'reject', or 'update_notes'

    useEffect(() => {
        if (currentUser && currentUser.accessToken && requestId) {
            fetchRequestDetails();
        }
    }, [currentUser, requestId]);

    const fetchRequestDetails = async () => {
        setLoading(true);
        setError(null);
        try {
            const token = localStorage.getItem('token');
            // This endpoint might need to be created or adjusted if not available
            // For now, assuming a general GET /api/medication-requests/{id} exists for nurses
            const response = await axios.get(`/api/medication-requests/all`, { // Temp: fetch all and filter, ideally GET /api/medication-requests/{id}
                headers: { Authorization: `Bearer ${token}` }
            });
            const foundRequest = response.data.find(r => r.requestId.toString() === requestId);
            if (foundRequest) {
                setRequest(foundRequest);
                setNurseNotes(foundRequest.notes || ''); // Initialize notes from request if present
            } else {
                setError('Medication request not found.');
            }
        } catch (err) {
            console.error("Error fetching medication request details:", err);
            setError('Failed to load request details.');
        } finally {
            setLoading(false);
        }
    };

    const handleAction = async () => {
        if (!confirmDialogAction) return;
        setOpenConfirmDialog(false);
        setActionInProgress(true);
        setError(null);

        const actionDTO = { notes: nurseNotes };
        let endpoint = '';
        let successMessage = '';

        switch(confirmDialogAction) {
            case 'approve':
                endpoint = `/api/medication-requests/${requestId}/approve`;
                successMessage = 'Medication request approved successfully.';
                break;
            case 'reject':
                endpoint = `/api/medication-requests/${requestId}/reject`;
                successMessage = 'Medication request rejected successfully.';
                break;
            case 'update_notes':
                endpoint = `/api/medication-requests/${requestId}/notes`;
                successMessage = 'Notes updated successfully.';
                break;
            default:
                setActionInProgress(false);
                return;
        }

        try {
            const token = localStorage.getItem('token');
            await axios.put(endpoint, actionDTO, {
                headers: { Authorization: `Bearer ${token}` }
            });
            alert(successMessage);
            fetchRequestDetails(); // Refresh data
        } catch (err) {
            console.error(`Error performing action (${confirmDialogAction}):`, err.response ? err.response.data : err.message);
            setError(`Failed to ${confirmDialogAction.replace('_', ' ')} request. ` + (err.response?.data?.message || 'Please try again.'));
        } finally {
            setActionInProgress(false);
            setConfirmDialogAction(null);
        }
    };

    const openConfirmation = (actionType) => {
        if (actionType !== 'update_notes' && request?.status !== 'PENDING') {
            alert(`This request is already ${request?.status?.toLowerCase()}. Only notes can be updated.`);
            return;
        }
        if (!nurseNotes && (actionType === 'reject' || actionType === 'approve')) {
            alert('Notes are required to approve or reject a request.');
            return;
        }
        setConfirmDialogAction(actionType);
        setOpenConfirmDialog(true);
    };

    const getStatusChipColor = (status) => {
        if (!status) return 'default';
        switch (status.toLowerCase()) {
            case 'pending': return 'warning';
            case 'approved': return 'success';
            case 'rejected': return 'error';
            case 'cancelled': return 'default';
            default: return 'info';
        }
    };

    if (loading) {
        return <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '80vh' }}><CircularProgress /></Box>;
    }

    if (error && !request) {
        return <Typography color="error" sx={{ textAlign: 'center', mt: 4 }}>{error}</Typography>;
    }
    
    if (!request) {
        return <Typography sx={{ textAlign: 'center', mt: 4 }}>Request not found or still loading.</Typography>;
    }

    return (
        <Paper elevation={3} sx={{ p: 3, maxWidth: 800, margin: 'auto', mt: 4 }}>
            <Typography variant="h4" gutterBottom sx={{ mb: 2, fontWeight: 'bold', color: 'primary.main' }}>
                Medication Request Review
            </Typography>
            
            {error && <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert>}

            <Grid container spacing={2}>
                <Grid item xs={12} sm={6}>
                    <Typography variant="subtitle1"><strong>Student:</strong> {request.student.fullName} ({request.student.studentCode})</Typography>
                    <Typography variant="subtitle1"><strong>Parent:</strong> {request.parent.user.firstName} {request.parent.user.lastName} ({request.parent.parentCode})</Typography>
                    <Typography variant="subtitle1"><strong>Requested:</strong> {new Date(request.requestDate).toLocaleString()}</Typography>
                </Grid>
                <Grid item xs={12} sm={6} sx={{ textAlign: { sm: 'right'} }}>
                     <Chip label={request.status} color={getStatusChipColor(request.status)} size="medium" />
                </Grid>

                <Grid item xs={12}><hr/></Grid>

                <Grid item xs={12} sm={6}>
                    <Typography variant="body1"><strong>Medication:</strong> {request.medicationName}</Typography>
                    <Typography variant="body1"><strong>Dosage:</strong> {request.dosage}</Typography>
                    <Typography variant="body1"><strong>Frequency:</strong> {request.frequency}</Typography>
                </Grid>
                <Grid item xs={12} sm={6}>
                    <Typography variant="body1"><strong>Start Date:</strong> {new Date(request.startDate).toLocaleDateString()}</Typography>
                    <Typography variant="body1"><strong>End Date:</strong> {new Date(request.endDate).toLocaleDateString()}</Typography>
                </Grid>
                
                <Grid item xs={12}>
                    <Typography variant="body1"><strong>Reason:</strong> {request.reason}</Typography>
                </Grid>
                
                {request.notes && (
                    <Grid item xs={12}>
                        <Typography variant="body1" sx={{ fontStyle: 'italic', color: 'text.secondary' }}>
                            <strong>Parent/Initial Notes:</strong> {request.notes}
                        </Typography>
                    </Grid>
                )}

                {request.approvedBy && (
                     <Grid item xs={12} sx={{ mt:1, pt:1, borderTop: '1px solid #eee' }}>
                        <Typography variant="body2" color="textSecondary">
                            Last action by: {request.approvedBy.user.firstName} {request.approvedBy.user.lastName} ({request.approvedBy.nurseCode}) on {new Date(request.actionDate).toLocaleString()}
                        </Typography>
                        {request.status !== 'PENDING' && request.notes && (
                             <Typography variant="body2" sx={{ fontStyle: 'italic', color: 'text.secondary' }}><strong>Nurse Notes (at action):</strong> {request.notes}</Typography>
                        )}
                    </Grid>
                )}
            </Grid>

            <Box sx={{ mt: 3, pt: 3, borderTop: '1px dashed #ccc' }}>
                <Typography variant="h6" gutterBottom>Nurse Action</Typography>
                <TextField
                    label="Nurse Notes / Comments"
                    multiline
                    rows={4}
                    fullWidth
                    value={nurseNotes}
                    onChange={(e) => setNurseNotes(e.target.value)}
                    variant="outlined"
                    sx={{ mb: 2 }}
                    disabled={actionInProgress || (request.status !== 'PENDING' && confirmDialogAction !== 'update_notes')}
                />
                <Grid container spacing={2} justifyContent="flex-end">
                    {request.status === 'PENDING' && (
                        <>
                            <Grid item>
                                <Button 
                                    variant="contained" 
                                    color="success" 
                                    startIcon={<CheckCircleOutlineIcon />}
                                    onClick={() => openConfirmation('approve')}
                                    disabled={actionInProgress}
                                >
                                    Approve
                                </Button>
                            </Grid>
                            <Grid item>
                                <Button 
                                    variant="contained" 
                                    color="error" 
                                    startIcon={<HighlightOffIcon />}
                                    onClick={() => openConfirmation('reject')}
                                    disabled={actionInProgress}
                                >
                                    Reject
                                </Button>
                            </Grid>
                        </>
                    )}
                    <Grid item>
                         <Button 
                            variant="outlined" 
                            color="primary" 
                            startIcon={<EditNoteIcon />}
                            onClick={() => openConfirmation('update_notes')}
                            disabled={actionInProgress}
                        >
                            {request.status === 'PENDING' ? 'Save Notes Only' : 'Update Notes'}
                        </Button>
                    </Grid>
                </Grid>
            </Box>

            <Dialog open={openConfirmDialog} onClose={() => setOpenConfirmDialog(false)}>
                <DialogTitle>Confirm Action</DialogTitle>
                <DialogContent>
                    <DialogContentText>
                        Are you sure you want to {confirmDialogAction?.replace('_', ' ')} this medication request?
                        { (confirmDialogAction === 'approve' || confirmDialogAction === 'reject') && nurseNotes && 
                            <Typography variant="caption" display="block" sx={{mt:1}}>Notes will be saved: "{nurseNotes.substring(0,100)}{nurseNotes.length > 100 ? '...' : ''}"</Typography> }
                    </DialogContentText>
                </DialogContent>
                <DialogActions>
                    <Button onClick={() => setOpenConfirmDialog(false)} color="primary">Cancel</Button>
                    <Button onClick={handleAction} color="primary" autoFocus disabled={actionInProgress}>
                        {actionInProgress ? <CircularProgress size={24} /> : 'Confirm'}
                    </Button>
                </DialogActions>
            </Dialog>

            <Button onClick={() => navigate(-1)} sx={{ mt: 3 }}>Back to List</Button>
        </Paper>
    );
};

export default MedicationRequestReview;
